import React, { PropsWithChildren } from "react";
import Flex from "../Flex";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /** If `true`, controls will be shown in a row */
  row?: boolean;
}>;

export type FormGroupProps = Props & CommonProps;

const FormGroup = ({ row, children, ...rest }: FormGroupProps) => (
  <Flex direction={row ? "row" : "column"} spacing="three-quarter-x" {...rest}>
    {children}
  </Flex>
);

export default FormGroup;
